using Test, Arrhenius, LinearAlgebra
if !isdefined(Arrhenius,:CounterflowDiffusionFlame)
    Base.include(Arrhenius,joinpath(@__DIR__,"..","src","CounterflowFlames.jl"))
end

# Layer-2 regression: native counterflow constructors must reproduce Cantera's
# initial grid and initial guess (onedim.py set_initial_guess of
# CounterflowDiffusionFlame, CounterflowPremixedFlame, CounterflowTwinPremixedFlame
# and ImpingingJet). References are generated by
# test/data/generate_counterflow_init_refs.py from the same mechanism/h2o2.yaml.
@testset "counterflow initial guess parity with Cantera" begin
    gas=CreateSolution(joinpath(dirname(pathof(Arrhenius)),"..","mechanism","h2o2.yaml"))
    function compare(f,reference)
        ref=Arrhenius.npzread(joinpath(@__DIR__,"data",reference))
        @test f.grid ≈ ref["grid"] atol=1e-15
        @test temperature(f) ≈ ref["T"] rtol=1e-9
        @test velocity(f) ≈ ref["velocity"] rtol=1e-9
        @test spread_rate(f) ≈ ref["spreadRate"] rtol=1e-9
        @test pressure_curvature(f) ≈ ref["Lambda"] rtol=1e-9
        @test mass_fractions(f) ≈ ref["Y"] atol=1e-9
        nothing
    end

    # The erf mixing layer does not saturate at the inlets, so the inlet
    # velocity guess is mdot/rho of the blended boundary state, not of the pure
    # inlet mixture (the pre-fix form pinned the exact inlet mass flux and was
    # ~1.5% off Cantera at both boundary velocities).
    diffusion=CounterflowDiffusionFlame(gas;fuel="H2:1,AR:1",oxidizer="O2:.2,AR:.8",
        mdot_fuel=.24,mdot_oxidizer=.72,T_fuel=300.,T_oxidizer=300.,P=one_atm,width=.02)
    compare(diffusion,"cantera_counterflow_diffusion_init.npz")

    composition="H2:1.6,O2:1,AR:7"; P=.05*one_atm
    premixed=CounterflowPremixedFlame(gas;reactants=composition,mdot_reactants=.12,
        mdot_products=.06,T_reactants=373.,P,width=.2)
    compare(premixed,"cantera_counterflow_premixed_init.npz")

    twin=CounterflowTwinPremixedFlame(gas;reactants=composition,mdot=.12,T=373.,P,width=.2)
    compare(twin,"cantera_counterflow_twin_init.npz")

    jet=ImpingingJet(gas;reactants=composition,mdot=.06,T_inlet=373.,T_surface=500.,P,width=.2)
    compare(jet,"cantera_counterflow_stagnation_init.npz")
end
